// Keep only requests that still need checking. Everything else (done, escalated, old rows without a status) is ignored.
const OPEN_STATUSES = ['open', 'closed_pending'];

const pending = $input.all()
  .map(i => i.json)
  .filter(r => r && r.issue_key && OPEN_STATUSES.includes(String(r.status || '').toLowerCase()));

// Nothing to check -> return no items, so the rest of the workflow does not run (no Jira call, no query).
if (pending.length === 0) return [];

return [{ json: { pending, pendingCount: pending.length } }];

// Match our pending requests against the closed Jira tickets, and build ONE verification payload for all of them.
const pending = $('Pick Pending').first().json.pending;

// Jira returns one item per closed ticket. With "Always Output Data" on, "no results" arrives as one empty item.
const closed = new Map();
for (const i of $input.all()) {
  if (i.json && i.json.key) closed.set(i.json.key, i.json);
}

// Jira Server dates look like "2026-09-28T10:00:00.000+0530"; add the colon so every JS engine parses them.
const toIso = s => {
  if (!s) return null;
  const d = new Date(String(s).replace(/([+-]\d{2})(\d{2})$/, '$1:$2'));
  return isNaN(d) ? null : d.toISOString();
};

const tickets = [];
const checks = [];          // one row per (ticket, mk_file_id, brand) -> sent to Postgres
const mkFileIds = new Set();

for (const r of pending) {
  const issue = closed.get(r.issue_key);
  if (!issue) continue;     // ticket not closed yet -> check again next run

  let companies = [];
  try { companies = JSON.parse(r.details_json || '[]'); } catch (e) { companies = []; }
  if (!Array.isArray(companies)) companies = [];

  let invalid = companies.length === 0;   // no details stored -> cannot verify automatically
  for (const c of companies) {
    const mk = String(c.mkFileId ?? '').trim();
    // Only digits allowed: this list is written straight into the SQL text (see Verify Brands), so it must be safe.
    if (!/^\d+$/.test(mk)) { invalid = true; continue; }
    mkFileIds.add(mk);
    for (const b of (Array.isArray(c.brands) ? c.brands : [])) {
      const brand = typeof b === 'object' && b ? b.brand : b;
      const epsilon = (typeof b === 'object' && b && b.epsilonBrand) || String(brand || '').toLowerCase();
      if (!brand) continue;
      checks.push({ issue_key: r.issue_key, mk_file_id: mk, brand: String(brand), epsilon_brand: String(epsilon) });
    }
  }

  tickets.push({
    rowId: r.id,
    issueKey: r.issue_key,
    status: String(r.status || '').toLowerCase(),
    requesterEmail: r.requester_email,
    requestType: r.request_type || 'new',
    summary: (issue.fields && issue.fields.summary) || r.issue_key,
    companies,
    // The 1-day clock starts at Jira's resolution date; if Jira has none, at the moment we first saw it closed.
    closedAt: r.closed_at ? toIso(r.closed_at) : (toIso(issue.fields && issue.fields.resolutiondate) || new Date().toISOString()),
    expectedChecks: checks.filter(c => c.issue_key === r.issue_key).length,
    invalid
  });
}

if (tickets.length === 0) return [];

return [{
  json: {
    tickets,
    // Base64 has no commas or quotes, so n8n passes it to Postgres as ONE parameter, untouched.
    payloadB64: Buffer.from(JSON.stringify(checks), 'utf8').toString('base64'),
    mkFileList: [...mkFileIds].join(', ') || '0'
  }
}];

// Decide what happens to each closed ticket: notify the requester, escalate to you, or wait for the next run.

// ---------- Settings: edit these ----------
const WAIT_HOURS = 24;                                    // how long after closing we wait for the data
const ADMIN_EMAIL = 'your.name@yourcompany.com';              // receives the "still not populated" alerts
const JIRA_BASE_URL = 'https://jira.yourcompany.com';     // used for the ticket link in emails
const TEST_EMAIL_OVERRIDE = '';                           // while testing, put your own address here: ALL emails go to it
// -------------------------------------------

const { tickets } = $('Match Closed').first().json;

// Verification rows from Postgres, grouped by ticket. ("Always Output Data" can add one empty item.)
const byKey = new Map();
for (const i of $input.all()) {
  const r = i.json;
  if (!r || !r.issue_key) continue;
  if (!byKey.has(r.issue_key)) byKey.set(r.issue_key, []);
  byKey.get(r.issue_key).push(r);
}

const esc = s => String(s ?? '').replace(/[&<>"']/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));
const isTrue = v => v === true || v === 't' || v === 'true';
const now = Date.now();
const out = [];

for (const t of tickets) {
  const rows = byKey.get(t.issueKey) || [];
  const missing = rows.filter(r => !isTrue(r.populated));
  const allPopulated = !t.invalid && t.expectedChecks > 0 && rows.length === t.expectedChecks && missing.length === 0;
  const hoursSinceClosed = (now - Date.parse(t.closedAt)) / 36e5;
  const link = `${JIRA_BASE_URL.replace(/\/+$/, '')}/browse/${encodeURIComponent(t.issueKey)}`;
  const kind = t.requestType === 'rerun' ? 'Re-run taxo' : 'Taxo';

  const table = rows.length ? `
    <table cellpadding="6" cellspacing="0" border="1" style="border-collapse:collapse;border-color:#d6dae1;font-size:14px">
      <tr style="background:#f0f2f5"><th align="left">mk_file_id</th><th align="left">brand_attr</th><th align="left">Epsilon Brand</th><th align="left">Status</th></tr>
      ${rows.map(r => `<tr><td>${esc(r.mk_file_id)}</td><td>${esc(r.brand)}</td><td>${esc(r.epsilon_brand)}</td><td>${isTrue(r.populated) ? '✅ Populated' : '⏳ Not found yet'}</td></tr>`).join('')}
    </table>` : '<p><em>No brand details were stored for this request, so it could not be verified automatically.</em></p>';

  const base = { rowId: t.rowId, issueKey: t.issueKey, closedAt: t.closedAt };

  if (allPopulated) {
    out.push({ json: { ...base,
      action: 'notify', newStatus: 'done', sendEmail: true,
      emailTo: TEST_EMAIL_OVERRIDE || t.requesterEmail,
      subject: `${t.issueKey} completed: ${t.summary}`,
      html: `<div style="font-family:Segoe UI,Arial,sans-serif;font-size:14px;color:#1d2330">
        <p>Hi,</p>
        <p>Your ${esc(kind)} request <a href="${esc(link)}">${esc(t.issueKey)}</a> has been completed, and we have verified that the Epsilon Brand values are now populated:</p>
        ${table}
        <p>Thanks,<br>TAXO Request automation</p></div>`
    } });
  } else if (hoursSinceClosed >= WAIT_HOURS) {
    out.push({ json: { ...base,
      action: 'escalate', newStatus: 'escalated', sendEmail: true,
      emailTo: TEST_EMAIL_OVERRIDE || ADMIN_EMAIL,
      subject: `[Action needed] ${t.issueKey} closed but Epsilon Brand not populated`,
      html: `<div style="font-family:Segoe UI,Arial,sans-serif;font-size:14px;color:#1d2330">
        <p><a href="${esc(link)}">${esc(t.issueKey)}</a> (${esc(t.summary)}) was closed more than ${WAIT_HOURS} hours ago,
        but ${t.invalid ? 'it could not be verified automatically' : `${missing.length} of ${rows.length} brand(s) are still not populated in whse.dim_mp_product_detail`}.</p>
        ${table}
        <p>Requester: ${esc(t.requesterEmail)}<br>The requester has <strong>not</strong> been emailed.
        To re-check later, set this row's status back to <code>closed_pending</code> and clear closed_at in the taxo_requests table.</p></div>`
    } });
  } else if (t.status === 'open') {
    // First time we see it closed: record that, no email yet.
    out.push({ json: { ...base, action: 'wait', newStatus: 'closed_pending', sendEmail: false } });
  }
  // Already closed_pending and still inside the wait window -> nothing to update this run.
}

return out;
